package me.kright.gametools.pga2d

import scala.annotation.targetName
import me.kright.gametools.flatarray.FlatDoubleSerializer


/**
 * A point with three homogeneous coordinates: (x/w, y/w) when w != 0, or an ideal point (a direction) when w == 0.
 * The grade-2 element of 2d PGA, stored in dual representation.
 * projectivePoint.exp is a Pga2dMotor (rotation around the point), and motor.log is a Pga2dProjectivePoint.
 *
 * Variable fields: x, y, w.
 * Basis blade coefficients: wy = -x, wx = y, xy = w.
 *
 * Generated by pgaNdCodeGen (me.kright.gametools.pga.codegen.scalagen.pga2d.runScalaCodeGen).
 * Do not edit by hand: change the generator and re-run it.
 */
final case class Pga2dProjectivePoint(x: Double = 0.0,
                                      y: Double = 0.0,
                                      w: Double = 0.0) derives CanEqual, FlatDoubleSerializer:

  inline def wy: Double = -x

  inline def wx: Double = y

  inline def xy: Double = w

  override def toString: String =
    s"Pga2dProjectivePoint(x = $x, y = $y, w = $w)"

  def dual: Pga2dLine =
    Pga2dLine(
      x = x,
      y = y,
      w = w,
    )

  def weight: Pga2dVector =
    Pga2dVector(
      x = x,
      y = y,
    )

  def bulk: Pga2dRotor =
    Pga2dRotor(
      s = 0.0,
      xy = w,
    )

  @targetName("unaryMinus")
  def unary_- : Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = -x,
      y = -y,
      w = -w,
    )

  def reverse: Pga2dProjectivePoint =
    -this

  def antiReverse: Pga2dProjectivePoint =
    this

  def bulkNormSquare: Double =
    w * w

  def bulkNorm: Double =
    Math.sqrt(bulkNormSquare)

  def normalizedByBulk =
    this / bulkNorm

  def weightNormSquare: Double =
    (x * x + y * y)

  def weightNorm: Double =
    Math.sqrt(weightNormSquare)

  def normalizedByWeight =
    this / weightNorm

  def normSquare: Double =
    (w * w + x * x + y * y)

  def norm: Double =
    Math.sqrt(normSquare)

  def normalizedByNorm =
    this / norm

  @targetName("times")
  def *(r: Double): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = r * x,
      y = r * y,
      w = r * w,
    )

  /** multiplies by the reciprocal: one division instead of one per component, at the cost of one extra rounding (~0.5 ulp) */
  @targetName("div")
  def /(r: Double): Pga2dProjectivePoint =
    this * (1.0 / r)

  @targetName("plus")
  def +(r: Pga2dProjectivePoint): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = (r.x + x),
      y = (r.y + y),
      w = (r.w + w),
    )

  @targetName("minus")
  def -(r: Pga2dProjectivePoint): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = (x - r.x),
      y = (y - r.y),
      w = (w - r.w),
    )

  def madd(r: Pga2dProjectivePoint, mult: Double): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = (x + mult * r.x),
      y = (y + mult * r.y),
      w = (w + mult * r.w),
    )

  @targetName("plus")
  def +(r: Pga2dPoint): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = (r.x + x),
      y = (r.y + y),
      w = (1.0 + w),
    )

  @targetName("minus")
  def -(r: Pga2dPoint): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = (x - r.x),
      y = (y - r.y),
      w = (-1.0 + w),
    )

  def madd(r: Pga2dPoint, mult: Double): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = (x + mult * r.x),
      y = (y + mult * r.y),
      w = (mult + w),
    )

  @targetName("plus")
  def +(r: Pga2dVector): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = (r.x + x),
      y = (r.y + y),
      w = w,
    )

  @targetName("minus")
  def -(r: Pga2dVector): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = (x - r.x),
      y = (y - r.y),
      w = w,
    )

  def madd(r: Pga2dVector, mult: Double): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = (x + mult * r.x),
      y = (y + mult * r.y),
      w = w,
    )

  /** componentwise product on the raw fields; NOT a geometric-algebra operation (basis-dependent) */
  def scale(r: Pga2dProjectivePoint): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = x * r.x,
      y = y * r.y,
      w = w * r.w,
    )

  /** componentwise 1/x on the raw fields (a zero field yields Infinity); NOT the multiplicative inverse */
  def reciprocal: Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = 1.0 / x,
      y = 1.0 / y,
      w = 1.0 / w,
    )

  def exp: Pga2dMotor =
    val len = bulkNorm
    val cos = Math.cos(len)

    // sin(x)/x = 1 - x^2/6 + x^4/120 - ...; at x <= 1e-5 the dropped x^4/120 <= 8.4e-23
    // relative term is far below 1e-17, so the second-order form is exact in double
    val sinDivLen = if (len > 1e-5) {
      Math.sin(len) / len
    } else {
      1.0 - (len * len) / 6.0
    }

    Pga2dMotor(
      s = cos,
      wx = sinDivLen * y,
      wy = -sinDivLen * x,
      xy = sinDivLen * w,
    )

  def exp(t: Double): Pga2dMotor =
    val len = bulkNorm * Math.abs(t)
    val cos = Math.cos(len)

    // sin(x)/x = 1 - x^2/6 + x^4/120 - ...; at x <= 1e-5 the dropped x^4/120 <= 8.4e-23
    // relative term is far below 1e-17, so the second-order form is exact in double
    val sinDivLen = if (len > 1e-5) {
      Math.sin(len) / len
    } else {
      1.0 - (len * len) / 6.0
    }

    Pga2dMotor(
      s = cos,
      wx = sinDivLen * t * y,
      wy = -sinDivLen * t * x,
      xy = sinDivLen * t * w,
    )

  def toMultivector: Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = 0.0,
      x = 0.0,
      y = 0.0,
      wx = y,
      wy = -x,
      xy = w,
      i = 0.0,
    )

  def toMotor: Pga2dMotor =
    Pga2dMotor(
      s = 0.0,
      wx = y,
      wy = -x,
      xy = w,
    )

  def toRotorUnsafe: Pga2dRotor =
    Pga2dRotor(
      s = 0.0,
      xy = w,
    )

  def toProjectiveTranslatorUnsafe: Pga2dProjectiveTranslator =
    Pga2dProjectiveTranslator(
      s = 0.0,
      wx = y,
      wy = -x,
    )

  def toTranslatorUnsafe: Pga2dTranslator =
    Pga2dTranslator(
      wx = y,
      wy = -x,
    )

  def toVectorUnsafe: Pga2dVector =
    Pga2dVector(
      x = x,
      y = y,
    )

  def toPointUnsafe: Pga2dPoint =
    Pga2dPoint(
      x = x,
      y = y,
    )

  /** divides by the weight; an ideal point (weight == 0) yields infinite or NaN coordinates */
  def toPoint: Pga2dPoint =
    val mult = (1.0 / w)
    Pga2dPoint(
      x = mult * x,
      y = mult * y,
    )

  /** fused -line.dot(point).geometric(line); w of the result is line.normSquare > 0, so w = 1 for a normalized line */
  def projectOntoLine(line: Pga2dLine): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = (line.y * (line.y * x - line.x * y) - line.w * line.x * w),
      y = (line.x * (line.x * y - line.y * x) - line.w * line.y * w),
      w = w * (line.x * line.x + line.y * line.y),
    )

  /** fused -line.dot(point).geometric(line); w of the result is line.normSquare > 0, so w = 1 for a normalized line */
  def projectOntoLine(line: Pga2dLineCentral): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = line.y * (line.y * x - line.x * y),
      y = line.x * (line.x * y - line.y * x),
      w = w * (line.x * line.x + line.y * line.y),
    )

  infix def geometric(r: Pga2dMotor): Pga2dMotor =
    Pga2dMotor(
      s = -r.xy * w,
      wx = (r.s * y + r.wy * w + r.xy * x),
      wy = (r.xy * y - r.s * x - r.wx * w),
      xy = r.s * w,
    )

  infix def geometric(r: Pga2dLine): Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = (r.x * y - r.y * x),
      x = r.y * w,
      y = -r.x * w,
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = (r.w * w + r.x * x + r.y * y),
    )

  infix def geometric(r: Pga2dProjectivePoint): Pga2dProjectiveTranslator =
    Pga2dProjectiveTranslator(
      s = -r.w * w,
      wx = (r.w * x - r.x * w),
      wy = (r.w * y - r.y * w),
    )

  infix def geometric(r: Pga2dRotor): Pga2dMotor =
    Pga2dMotor(
      s = -r.xy * w,
      wx = (r.s * y + r.xy * x),
      wy = (r.xy * y - r.s * x),
      xy = r.s * w,
    )

  infix def geometric(r: Pga2dProjectiveTranslator): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = (r.s * x + r.wx * w),
      y = (r.s * y + r.wy * w),
      w = r.s * w,
    )

  infix def geometric(r: Pga2dTranslator): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = (x + r.wx * w),
      y = (y + r.wy * w),
      w = w,
    )

  infix def geometric(r: Pga2dVector): Pga2dVector =
    Pga2dVector(
      x = r.y * w,
      y = -r.x * w,
    )

  infix def geometric(r: Pga2dPoint): Pga2dProjectiveTranslator =
    Pga2dProjectiveTranslator(
      s = -w,
      wx = (x - r.x * w),
      wy = (y - r.y * w),
    )

  infix def geometric(r: Pga2dLineCentral): Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = (r.x * y - r.y * x),
      x = r.y * w,
      y = -r.x * w,
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = (r.x * x + r.y * y),
    )

  infix def geometric(r: Pga2dPseudoScalar): Pga2dLine =
    Pga2dLine(
      x = 0.0,
      y = 0.0,
      w = -r.i * w,
    )

  infix def geometric(r: Pga2dPointCenter.type): Pga2dProjectiveTranslator =
    Pga2dProjectiveTranslator(
      s = -w,
      wx = x,
      wy = y,
    )

  infix def dot(r: Pga2dMotor): Pga2dMotor =
    Pga2dMotor(
      s = -r.xy * w,
      wx = r.s * y,
      wy = -r.s * x,
      xy = r.s * w,
    )

  infix def dot(r: Pga2dLine): Pga2dLine =
    Pga2dLine(
      x = r.y * w,
      y = -r.x * w,
      w = (r.x * y - r.y * x),
    )

  infix def dot(r: Pga2dProjectivePoint): Double =
    -r.w * w

  infix def dot(r: Pga2dRotor): Pga2dMotor =
    Pga2dMotor(
      s = -r.xy * w,
      wx = r.s * y,
      wy = -r.s * x,
      xy = r.s * w,
