  infix def dot(r: Pga2dProjectiveTranslator): Pga2dProjectivePoint =
    Pga2dProjectivePoint(
      x = r.s * x,
      y = r.s * y,
      w = r.s * w,
    )

  infix def dot(r: Pga2dTranslator): Pga2dProjectivePoint =
    this

  infix def dot(r: Pga2dPoint): Double =
    -w

  infix def dot(r: Pga2dLineCentral): Pga2dLine =
    Pga2dLine(
      x = r.y * w,
      y = -r.x * w,
      w = (r.x * y - r.y * x),
