  inline infix def ^(r: Pga2dProjectiveTranslator): Pga2dProjectivePoint = wedge(r)

  inline infix def meet(r: Pga2dProjectiveTranslator): Pga2dProjectivePoint = wedge(r)

  infix def wedge(r: Pga2dTranslator): Pga2dProjectivePoint =
    this

  inline infix def ^(r: Pga2dTranslator): Pga2dProjectivePoint = wedge(r)

  inline infix def meet(r: Pga2dTranslator): Pga2dProjectivePoint = wedge(r)

  infix def wedge(r: Pga2dLineCentral): Pga2dPseudoScalar =
