  infix def antiGeometric(r: Pga2dMotor): Pga2dMultivector =
    Pga2dMultivector(
      s = 0.0,
      w = (r.wx * x + r.wy * y),
      x = (r.s * x + r.xy * y - r.wx * w),
      y = (r.s * y - r.wy * w - r.xy * x),
      wx = 0.0,
      wy = 0.0,
      xy = 0.0,
      i = (r.wx * y - r.wy * x),
    )

  infix def antiGeometric(r: Pga2dLine): Pga2dMotor =
    Pga2dMotor(
      s = (r.w * w + r.x * x + r.y * y),
